<?php
namespace App\Http\Controllers;
use App\Models\{MembershipTransaction,Member,MembershipLevel};use Illuminate\Http\Request;use Illuminate\Support\Str;
class TransactionController extends Controller {private function admin(){abort_unless(auth()->user()->role==='admin',403);} public function index(){ $this->admin();$transactions=MembershipTransaction::with(['member','level','payments'])->latest()->paginate(15);return view('transactions.index',compact('transactions'));} public function create(){ $this->admin();return view('transactions.create',['members'=>Member::where('status','Active')->get(),'levels'=>MembershipLevel::where('is_active',true)->get()]);} public function store(Request $r){$this->admin();$d=$r->validate(['member_id'=>'required|exists:members,id','membership_level_id'=>'required|exists:membership_levels,id','type'=>'required|in:application,renewal']);$level=MembershipLevel::findOrFail($d['membership_level_id']);$tx=MembershipTransaction::create(['reference_number'=>'PUH-TX-'.now()->format('Ymd').'-'.Str::upper(Str::random(6)),'member_id'=>$d['member_id'],'membership_level_id'=>$level->id,'type'=>$d['type'],'amount'=>$level->fee,'amount_paid'=>0,'status'=>$level->fee <= 0 ? 'Paid' : 'Pending','transaction_date'=>now()->toDateString()]);return redirect()->route('transactions.show',$tx)->with('success','Transaction created. Record payment to proceed.');} public function show(MembershipTransaction $transaction){$this->admin();$transaction->load(['member','level','payments']);return view('transactions.show',compact('transaction'));} public function approve(MembershipTransaction $transaction){$this->admin();abort_unless($transaction->status==='Paid',422,'Only fully paid transactions can be approved.');\DB::transaction(function()use($transaction){$transaction->update(['status'=>'Approved','approved_at'=>now()]);$member=$transaction->member;$months=$transaction->level->validity_months;$start=($transaction->type==='renewal'&&$member->expires_at&&$member->expires_at->isFuture())?$member->expires_at:now();$member->update(['membership_level_id'=>$transaction->membership_level_id,'level'=>$transaction->level->name,'joined_at'=>$member->joined_at??now()->toDateString(),'expires_at'=>$start->copy()->addMonths($months)->toDateString(),'status'=>'Active']);});return back()->with('success','Membership approved and validity updated.');} public function cancel(MembershipTransaction $transaction){$this->admin();abort_if(in_array($transaction->status,['Approved','Cancelled']),422,'This transaction can no longer be cancelled.');$transaction->update(['status'=>'Cancelled']);return back()->with('success','Transaction cancelled.');}}
